d=pd.read_csv(src);d['year']=d.month.str[:4].astype(int);d['lease']=d.remaining_lease.str.extract(r'(\d+) years')[0].astype(int)+d.remaining_lease.str.extract(r'(\d+) months')[0].fillna(0).astype(int)/12;d['psm']=d.resale_price/d.floor_area_sqm
bins=[0,50,60,70,80,100]; labels=['Under 50','50–<60','60–<70','70–<80','80–99'];d['band']=pd.cut(d.lease,bins,right=False,labels=labels)
latest=d[d.year==2025]
annual=[dict(name=str(y),v=float(g.resale_price.median()),n=len(g)) for y,g in d.groupby('year')]
