box=[]
for b,g in latest.groupby('band',observed=True):
 v=g.psm; q1,md,q3=v.quantile([.25,.5,.75]); inside=v[(v>=q1-1.5*(q3-q1))&(v<=q3+1.5*(q3-q1))]; outs=v[~v.index.isin(inside.index)]
 box.append(dict(name=str(b),q=[float(inside.min()),float(q1),float(md),float(q3),float(inside.max())],outs=list(map(float,outs)),n=len(g)))
types=['2 ROOM','3 ROOM','4 ROOM','5 ROOM','EXECUTIVE'];paired=[]
for t in types:
 g=d[d.flat_type==t];a=g[g.year==2017];b=g[g.year==2025];paired.append(dict(name=t.replace(' ROOM','-room').title(),a=float(a.resale_price.median()),b=float(b.resale_price.median()),na=len(a),nb=len(b)))
matrix=[dict(year=int(y),band=str(b),n=len(g)) for (y,b),g in d.groupby(['year','band'],observed=True)]
