ledger=r'''
let records=[],selected=[],page=0;const size=50;
function parseCSV(text){const result=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){cell+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(cell);cell=''}else if(c==='\n'&&!quote){row.push(cell.replace(/\r$/,''));result.push(row);row=[];cell=''}else cell+=c}if(cell||row.length){row.push(cell);result.push(row)}return result}
const enc=PAYLOAD;document.getElementById('load').onclick=async()=>{const bytes=Uint8Array.from(atob(enc),c=>c.charCodeAt(0));const text=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).text();const parsed=parseCSV(text);window.cols=parsed.shift();records=parsed;selected=records.map((r,i)=>i);document.getElementById('load').hidden=true;show()};
function show(){const box=document.getElementById('table');box.replaceChildren();const table=document.createElement('table');const header=document.createElement('tr');['Record ID',...cols].forEach(v=>{const th=document.createElement('th');th.textContent=v;header.append(th)});table.append(header);selected.slice(page*size,(page+1)*size).forEach(i=>{const tr=document.createElement('tr');[i+1,...records[i]].forEach(v=>{const td=document.createElement('td');td.textContent=v;tr.append(td)});table.append(tr)});box.append(table);document.getElementById('status').textContent=`${selected.length.toLocaleString()} records · page ${page+1} of ${Math.max(1,Math.ceil(selected.length/size))}`}
document.getElementById('query').oninput=e=>{if(!records.length)return;const q=e.target.value.toLowerCase();selected=records.flatMap((r,i)=>r.join(' ').toLowerCase().includes(q)?[i]:[]);page=0;show()};document.getElementById('prev').onclick=()=>{if(page>0){page--;show()}};document.getElementById('next').onclick=()=>{if((page+1)*size<selected.length){page++;show()}};
'''
